-- Generated by HyprMod

-- Environment
hl.env("QT_QPA_PLATFORMTHEME", "qt6ct")

-- Settings
hl.config({
    decoration = {
        blur = {
            passes = 3,
            size = 4,
        },
        inactive_opacity = 1.0,
        rounding = 0,
    },
    general = {
        allow_tearing = false,
        col = {
            active_border = {
                colors = {"rgba(e01b24ff)", "rgba(f5c211ff)"},
                angle = 45,
            },
            inactive_border = "0xaa595959",
        },
        gaps_out = 10,
        layout = "dwindle",
