        },
    },
    gestures = {
        workspace_swipe_forever = true,
    },
    misc = {
        disable_splash_rendering = false,
    },
})

-- Bezier curves
hl.curve("almostLinear", { type = "bezier", points = { {0.5, 0.5}, {0.75, 1.0} } })

-- Animations
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 1.94,
    bezier = "almostLinear",
    style = "slide",
})

-- Monitors
hl.monitor({
    output = "HDMI-A-1",
    disabled = false,
    mode = "1920x1080@100.00Hz",
    position = "-1920x190",
    scale = 1,
    cm = "srgb",
})
hl.monitor({
    output = "eDP-1",
    disabled = false,
    mode = "1920x1080@59.98Hz",
    position = "0x190",
    scale = 1,
    cm = "srgb",
})

-- Keybinds
hl.unbind("SUPER + Return")
hl.bind("SUPER + Return", hl.dsp.exec_cmd("kitty"))
hl.unbind("SUPER + space")
hl.bind("SUPER + space", hl.dsp.exec_cmd("rofi -show filebrowser"))
hl.unbind("SUPER + R")
hl.bind("ALT + space", hl.dsp.exec_cmd("rofi -show drun"))
hl.unbind("SUPER + W")
hl.bind("SUPER + W", hl.dsp.exec_cmd("google-chrome-stable"))
hl.unbind("SUPER + Q")
hl.bind("SUPER + Q", hl.dsp.window.close())
hl.unbind("SUPER + T")
hl.bind("SUPER + T", hl.dsp.window.float({ action = "toggle" }))
hl.unbind("SUPER + SHIFT + S")
hl.bind("SUPER + SHIFT + S", hl.dsp.exec_cmd("grim -g \"$(slurp)\" - | wl-copy"))
hl.unbind("SUPER + SHIFT + W")
hl.bind("SUPER + SHIFT + W", hl.dsp.exec_cmd("waypaper --random"))
hl.unbind("SUPER + I")
hl.bind("SUPER + I", hl.dsp.exec_cmd("hyprmod"))
hl.unbind("SUPER + B")
hl.bind("SUPER + B", hl.dsp.exec_cmd("wlogout -b 5"))
hl.unbind("SUPER + SHIFT + R")
hl.bind("SUPER + SHIFT + R", hl.dsp.exec_cmd("killall -SIGUSR2 waybar"))
hl.unbind("SUPER + F")
hl.bind("SUPER + F", hl.dsp.window.fullscreen())
hl.unbind("SUPER + SHIFT + F")
hl.bind("SUPER + SHIFT + F", hl.dsp.exec_raw("kitty -e fzf"))
hl.unbind("SUPER + E")
hl.bind("SUPER + E", hl.dsp.exec_cmd("nemo"))
hl.unbind("SUPER + V")
hl.bind("SUPER + V", hl.dsp.exec_cmd("cliphist list | rofi -dmenu -display-columns 2 | cliphist decode | wl-copy"))
hl.unbind("SUPER + ALT + V")
hl.bind("SUPER + ALT + V", hl.dsp.exec_cmd("cliphist wipe"))
hl.bind("SUPER + SHIFT + KP_Multiply", hl.dsp.exec_cmd("rofi -show calc -modi calc -no-show-match -no-sort"))

-- Layer rules
hl.layer_rule({
    name = "hyprwave",
    match = {
        namespace = "hyprwave",
    },
    xray = true,
})

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("waypaper --random")
    hl.exec_cmd("waybar")
    hl.exec_cmd("wl-paste --type text --watch cliphist store")
    hl.exec_cmd("wl-paste --type image --watch cliphist store")
end)
